//! Compile-time capability manifests for the aggregated frontend.
//!
//! The manifests are generated by `scripts/gen_capabilities.py` from the actual
//! `.route()` registrations in each component's `main.rs`, and embedded here as
//! static strings. No runtime endpoint is added: the 18 mandatory contract
//! endpoints stay unchanged, and the offline console keeps working with zero
//! network round-trips for its own layout.

pub const LAN_MDNS: &str =
    include_str!("../../../contracts/examples/capabilities.lan-mdns.sample.json");
pub const LAN_RELAY: &str =
    include_str!("../../../contracts/examples/capabilities.lan-relay.sample.json");
pub const LAN_CA: &str =
    include_str!("../../../contracts/examples/capabilities.lan-ca.sample.json");
pub const LAN_SCAN: &str =
    include_str!("../../../contracts/examples/capabilities.lan-scan.sample.json");
pub const LAN_HOSTS: &str =
    include_str!("../../../contracts/examples/capabilities.lan-hosts.sample.json");
pub const LAN_WOL: &str =
    include_str!("../../../contracts/examples/capabilities.lan-wol.sample.json");
pub const LAN_SYNC: &str =
    include_str!("../../../contracts/examples/capabilities.lan-sync.sample.json");
pub const LAN_SSDP: &str =
    include_str!("../../../contracts/examples/capabilities.lan-ssdp.sample.json");

const ALL: [(&str, &str); 8] = [
    ("lan-mdns", LAN_MDNS),
    ("lan-relay", LAN_RELAY),
    ("lan-ca", LAN_CA),
    ("lan-scan", LAN_SCAN),
    ("lan-hosts", LAN_HOSTS),
    ("lan-wol", LAN_WOL),
    ("lan-sync", LAN_SYNC),
    ("lan-ssdp", LAN_SSDP),
];

/// Capabilities of one component, used by each standalone binary's console.
pub fn for_component(name: &str) -> Option<&'static str> {
    ALL.iter()
        .find(|(key, _)| *key == name)
        .map(|(_, json)| *json)
}

/// All eight manifests as a JSON array, used by the Lan Studio Shell SPA.
pub fn all_json() -> String {
    let items: Vec<&str> = ALL.iter().map(|(_, json)| *json).collect();
    format!("[{}]", items.join(","))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_manifest_is_valid_json_and_matches_its_component() {
        for (name, json) in ALL {
            let text = json.trim();
            assert!(text.starts_with('{') && text.ends_with('}'), "{name}");
            assert!(
                text.contains(&format!("\"component\":\"{name}\""))
                    || text.contains(&format!("\"component\": \"{name}\"")),
                "{name}"
            );
            assert!(text.contains("\"modules\""), "{name}");
        }
    }

    #[test]
    fn unknown_component_has_no_manifest() {
        assert!(for_component("lan-unknown").is_none());
        assert!(for_component("lan-wol").is_some());
    }

    #[test]
    fn all_json_is_a_json_array_of_eight() {
        let text = all_json();
        assert!(text.starts_with('[') && text.ends_with(']'));
        assert_eq!(text.matches("\"component\"").count(), 8);
    }
}
